; logic.asm -- chapter 10: AND, OR and XOR on every pair, counted by F
; generated by gen10.py
        INCLUDE "msx.inc"
        OUTPUT "logic.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
init:   di
        ld sp, SYS_AREA
COUNTS  EQU $D000               ; in the RAM: 256 counters of two bytes for each operation
        ld hl, COUNTS
        ld de, COUNTS + 1
        ld (hl), 0
        ld bc, 1536 - 1
        ldir                    ; every counter to 0
; and: counters at $D000 (low bytes) and $D100 (high bytes)
        ld d, 0                 ; D: the first number
and1:   ld e, 0                 ; E: the second
and2:   ld a, d
        and e                   ; the operation counted
        push af
        pop bc                  ; C = F
        ld h, $D0               ; the page of low bytes
        ld l, c                 ; the counter for this value of F
        inc (hl)
        jr nz, and3
        inc h
        inc (hl)                ; the carry into its high byte
and3:   inc e
        jr nz, and2             ; all 256 values of E
        inc d
        jr nz, and1             ; for all 256 values of D
; or: counters at $D200 (low bytes) and $D300 (high bytes)
        ld d, 0                 ; D: the first number
or1:    ld e, 0                 ; E: the second
or2:    ld a, d
        or e                    ; the operation counted
        push af
        pop bc                  ; C = F
        ld h, $D2               ; the page of low bytes
        ld l, c                 ; the counter for this value of F
        inc (hl)
        jr nz, or3
        inc h
        inc (hl)                ; the carry into its high byte
or3:    inc e
        jr nz, or2              ; all 256 values of E
        inc d
        jr nz, or1              ; for all 256 values of D
; xor: counters at $D400 (low bytes) and $D500 (high bytes)
        ld d, 0                 ; D: the first number
xor1:   ld e, 0                 ; E: the second
xor2:   ld a, d
        xor e                   ; the operation counted
        push af
        pop bc                  ; C = F
        ld h, $D4               ; the page of low bytes
        ld l, c                 ; the counter for this value of F
        inc (hl)
        jr nz, xor3
        inc h
        inc (hl)                ; the carry into its high byte
xor3:   inc e
        jr nz, xor2             ; all 256 values of E
        inc d
        jr nz, xor1             ; for all 256 values of D
stop:   jr stop
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
